int len;

long long bestSum;
int bestCuts[MAXD];
int bestCnt;
int bestType; /* 0 = none, 1 = unique, 2 = rejected */

long long parts[MAXD];
int cuts[MAXD]; /* cut positions after index i */

void evaluate_partition() {
    long long sum = 0;
    int cnt = 0;
    int start = 0;

    for (int i = 0; i < len; i++) {
        if (cuts[i]) {
            long long val = 0;
            for (int j = start; j <= i; j++) {
                val = val * 10 + (s[j] - '0');
            }
            parts[cnt++] = val;
            sum += val;
            start = i + 1;
        }
    }

    if (sum > target) return;

    if (bestType == 0 || sum > bestSum) {
        bestSum = sum;
        bestType = 1;
        bestCnt = cnt;
        for (int i = 0; i < len; i++) bestCuts[i] = cuts[i];
    } else if (sum == bestSum) {
        int same = 1;
        for (int i = 0; i < len; i++) {
            if (bestCuts[i] != cuts[i]) {
                same = 0;
                break;
            }
        }
        if (!same) bestType = 2;
    }
}

void dfs(int pos) {
    if (pos == len - 1) {
        cuts[pos] = 1; /* always cut at the end */
        evaluate_partition();
        return;
    }

    cuts[pos] = 0;
    dfs(pos + 1);

    cuts[pos] = 1;
    dfs(pos + 1);
}

