public class ShreddingCompany {

    static int target;
    static String paper;
    static int bestSum;
    static List<Integer> bestParts;
    static boolean rejected;
    static boolean found;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        while (true) {
            String line = br.readLine();
            if (line == null || line.trim().isEmpty()) continue;
            String[] parts = line.split(" ");
            target = Integer.parseInt(parts[0]);
            paper = parts[1];

            if (target == 0 && paper.equals("0")) break;

            bestSum = -1;
            bestParts = null;
            rejected = false;
            found = false;

            // If paper number equals target, output the number itself
            if (Integer.parseInt(paper) == target) {
                out.println(target + " " + target);
                continue;
            }

            dfs(0, 0, new ArrayList<>());

            if (!found) {
                out.println("error");
            } else if (rejected) {
                out.println("rejected");
            } else {
                StringBuilder sb = new StringBuilder();
                sb.append(bestSum);
                for (int num : bestParts) {
                    sb.append(" ").append(num);
                }
                out.println(sb.toString());
            }
        }

        out.flush();
        out.close();
        br.close();
    }

    static void dfs(int index, int currentSum, List<Integer> currentParts) {
        if (currentSum > target) return;

        if (index == paper.length()) {
            if (currentSum <= target) {
                if (currentSum > bestSum) {
                    bestSum = currentSum;
                    bestParts = new ArrayList<>(currentParts);
                    rejected = false;
                    found = true;
                } else if (currentSum == bestSum) {
                    rejected = true;
                }
            }
            return;
        }

        for (int end = index + 1; end <= paper.length(); end++) {
            String sub = paper.substring(index, end);
            // Skip leading zeros but not single zero
            if (sub.length() > 1 && sub.charAt(0) == '0') continue;
            int num = Integer.parseInt(sub);
            if (num > target) break; // further substrings will be larger

            currentParts.add(num);
            dfs(end, currentSum + num, currentParts);
            currentParts.remove(currentParts.size() - 1);
        }
    }
}

