public class Main {
    static String digits;
    static List<List<String>> allPartitions = new ArrayList<>();

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int T = sc.nextInt(), N = sc.nextInt();
            if (T == 0 && N == 0) break;

            digits = Integer.toString(N);
            allPartitions.clear();
            generatePartitions(0, new ArrayList<>());

            if (T == N) {
                System.out.println(T + " " + digits);
                continue;
            }

            int bestSum = -1;
            List<List<String>> bestPartitions = new ArrayList<>();

            for (List<String> partition : allPartitions) {
                int sum = 0;
                for (String p : partition) sum += Integer.parseInt(p);
                if (sum <= T) {
                    if (sum > bestSum) {
                        bestSum = sum;
                        bestPartitions.clear();
                        bestPartitions.add(partition);
                    } else if (sum == bestSum) {
                        bestPartitions.add(partition);
                    }
                }
            }

            if (bestSum == -1) System.out.println("error");
            else if (bestPartitions.size() > 1) System.out.println("rejected");
            else {
                StringBuilder sb = new StringBuilder();
                sb.append(bestSum);
                for (String p : bestPartitions.get(0)) sb.append(" ").append(p);
                System.out.println(sb.toString());
            }
        }
    }

    static void generatePartitions(int idx, List<String> current) {
        if (idx == digits.length()) {
            allPartitions.add(new ArrayList<>(current));
            return;
        }
        for (int end = idx + 1; end <= digits.length(); end++) {
            current.add(digits.substring(idx, end));
            generatePartitions(end, current);
            current.remove(current.size() - 1);
        }
    }
}

