import sys

def solve():
    data = sys.stdin.read().strip().split()
    out_lines = []
    idx = 0
    while idx < len(data):
        target = int(data[idx])
        num_str = data[idx+1]
        idx += 2
        if target == 0 and num_str == "0":
            break

        n = len(num_str)
        best_sum = -1
        best_parts = None
        count_best = 0

        # Use DFS to try all ways to split the string
        def dfs(pos, current_sum, parts):
            nonlocal best_sum, best_parts, count_best
            if pos == n:
                if current_sum <= target:
                    if current_sum > best_sum:
                        best_sum = current_sum
                        best_parts = parts[:]
                        count_best = 1
                    elif current_sum == best_sum:
                        count_best += 1
                return
            # Try all possible end positions for the next piece
            for end in range(pos+1, n+1):
                piece_str = num_str[pos:end]
                # Avoid numbers with leading zeros (except single zero)
                if len(piece_str) > 1 and piece_str[0] == '0':
                    continue
                piece_val = int(piece_str)
                if current_sum + piece_val > target:
                    continue
                dfs(end, current_sum + piece_val, parts + [piece_val])

        dfs(0, 0, [])

        if best_sum == -1:
            out_lines.append("error")
        elif count_best > 1:
            out_lines.append("rejected")
        else:
            out_lines.append(f"{best_sum} " + " ".join(map(str, best_parts)))

    sys.stdout.write("\n".join(out_lines))

