import sys

def solve_case(target: int, num_str: str) -> str:
    n = len(num_str)
    best_sum = -1
    best_parts = None
    rejected = False

    # Enumerate all ways to split digits using bitmask on cut positions
    # bit i means cut after position i
    for mask in range(1 << (n - 1)):
        parts = []
        cur = num_str[0]
        total = 0

        for i in range(n - 1):
            if (mask >> i) & 1:
                val = int(cur)
                total += val
                if total > target:
                    break
                parts.append(val)
                cur = num_str[i + 1]
            else:
                cur += num_str[i + 1]
        else:
            val = int(cur)
            total += val
            if total <= target:
                parts.append(val)
                if total > best_sum:
                    best_sum = total
                    best_parts = parts[:]
                    rejected = False
                elif total == best_sum:
                    rejected = True

    if best_sum == -1:
        return "error"
    if rejected:
        return "rejected"
    return str(best_sum) + " " + " ".join(map(str, best_parts))

